// Sound Manager for Go Fish game

class SoundManager {
  constructor() {
    this.sounds = {};
    this.music = null;
    this.soundEnabled = true;
    this.musicEnabled = true;
    this.musicVolume = 0.3;
    this.soundVolume = 0.5;
    this.initialized = false;
  }

  init() {
    if (this.initialized) return;
    
    // Create sound effects using Web Audio API oscillators (no external files needed)
    this.audioContext = new (window.AudioContext || window.webkitAudioContext)();
    this.initialized = true;
  }

  // Play a beep/tone sound effect
  playTone(frequency, duration, type = 'sine') {
    if (!this.soundEnabled) return;
    
    try {
      this.init();
      const oscillator = this.audioContext.createOscillator();
      const gainNode = this.audioContext.createGain();
      
      oscillator.connect(gainNode);
      gainNode.connect(this.audioContext.destination);
      
      oscillator.frequency.value = frequency;
      oscillator.type = type;
      
      gainNode.gain.setValueAtTime(this.soundVolume * 0.3, this.audioContext.currentTime);
      gainNode.gain.exponentialRampToValueAtTime(0.01, this.audioContext.currentTime + duration);
      
      oscillator.start(this.audioContext.currentTime);
      oscillator.stop(this.audioContext.currentTime + duration);
    } catch (e) {
      console.log('Sound not available');
    }
  }

  // Sound effects
  playCardSelect() {
    this.playTone(800, 0.1, 'sine');
  }

  playCardDraw() {
    this.playTone(400, 0.15, 'triangle');
    setTimeout(() => this.playTone(500, 0.1, 'triangle'), 50);
  }

  playGoFish() {
    this.playTone(300, 0.2, 'sawtooth');
    setTimeout(() => this.playTone(250, 0.3, 'sawtooth'), 100);
  }

  playSuccess() {
    this.playTone(523, 0.1, 'sine');
    setTimeout(() => this.playTone(659, 0.1, 'sine'), 100);
    setTimeout(() => this.playTone(784, 0.15, 'sine'), 200);
  }

  playBook() {
    this.playTone(523, 0.1, 'sine');
    setTimeout(() => this.playTone(659, 0.1, 'sine'), 100);
    setTimeout(() => this.playTone(784, 0.1, 'sine'), 200);
    setTimeout(() => this.playTone(1047, 0.2, 'sine'), 300);
  }

  playGameOver() {
    this.playTone(784, 0.2, 'sine');
    setTimeout(() => this.playTone(659, 0.2, 'sine'), 200);
    setTimeout(() => this.playTone(523, 0.2, 'sine'), 400);
    setTimeout(() => this.playTone(784, 0.3, 'sine'), 600);
  }

  playWin() {
    const notes = [523, 587, 659, 784, 659, 784, 1047];
    notes.forEach((freq, i) => {
      setTimeout(() => this.playTone(freq, 0.15, 'sine'), i * 100);
    });
  }

  playLose() {
    this.playTone(400, 0.3, 'sawtooth');
    setTimeout(() => this.playTone(300, 0.3, 'sawtooth'), 200);
    setTimeout(() => this.playTone(200, 0.5, 'sawtooth'), 400);
  }

  playClick() {
    this.playTone(600, 0.05, 'sine');
  }

  // Background music using oscillators
  startMusic() {
    if (!this.musicEnabled || this.musicPlaying) return;
    
    try {
      this.init();
      this.musicPlaying = true;
      this.playMusicLoop();
    } catch (e) {
      console.log('Music not available');
    }
  }

  playMusicLoop() {
    if (!this.musicPlaying || !this.musicEnabled) return;

    // Simple calm melody loop
    const melody = [
      { freq: 329, dur: 0.4 }, // E4
      { freq: 392, dur: 0.4 }, // G4
      { freq: 440, dur: 0.4 }, // A4
      { freq: 392, dur: 0.4 }, // G4
      { freq: 329, dur: 0.4 }, // E4
      { freq: 294, dur: 0.4 }, // D4
      { freq: 329, dur: 0.8 }, // E4
      { freq: 0, dur: 0.4 },   // rest
      { freq: 392, dur: 0.4 }, // G4
      { freq: 440, dur: 0.4 }, // A4
      { freq: 494, dur: 0.4 }, // B4
      { freq: 440, dur: 0.4 }, // A4
      { freq: 392, dur: 0.4 }, // G4
      { freq: 329, dur: 0.8 }, // E4
      { freq: 0, dur: 0.4 },   // rest
    ];

    let time = 0;
    melody.forEach(note => {
      if (note.freq > 0) {
        setTimeout(() => {
          if (this.musicPlaying && this.musicEnabled) {
            this.playMusicNote(note.freq, note.dur * 0.9);
          }
        }, time * 1000);
      }
      time += note.dur;
    });

    // Loop the melody
    setTimeout(() => {
      if (this.musicPlaying && this.musicEnabled) {
        this.playMusicLoop();
      }
    }, time * 1000);
  }

  playMusicNote(frequency, duration) {
    try {
      const oscillator = this.audioContext.createOscillator();
      const gainNode = this.audioContext.createGain();
      
      oscillator.connect(gainNode);
      gainNode.connect(this.audioContext.destination);
      
      oscillator.frequency.value = frequency;
      oscillator.type = 'sine';
      
      const volume = this.musicVolume * 0.15;
      gainNode.gain.setValueAtTime(0, this.audioContext.currentTime);
      gainNode.gain.linearRampToValueAtTime(volume, this.audioContext.currentTime + 0.05);
      gainNode.gain.setValueAtTime(volume, this.audioContext.currentTime + duration - 0.05);
      gainNode.gain.linearRampToValueAtTime(0, this.audioContext.currentTime + duration);
      
      oscillator.start(this.audioContext.currentTime);
      oscillator.stop(this.audioContext.currentTime + duration);
    } catch (e) {
      // Ignore errors
    }
  }

  stopMusic() {
    this.musicPlaying = false;
  }

  toggleSound() {
    this.soundEnabled = !this.soundEnabled;
    return this.soundEnabled;
  }

  toggleMusic() {
    this.musicEnabled = !this.musicEnabled;
    if (this.musicEnabled) {
      this.startMusic();
    } else {
      this.stopMusic();
    }
    return this.musicEnabled;
  }

  setSoundEnabled(enabled) {
    this.soundEnabled = enabled;
  }

  setMusicEnabled(enabled) {
    this.musicEnabled = enabled;
    if (enabled) {
      this.startMusic();
    } else {
      this.stopMusic();
    }
  }
}

// Singleton instance
const soundManager = new SoundManager();
export default soundManager;
